export function normalizeUserRoles(raw: readonly string[]): string[] {
  const seen = new Set<string>();
  for (const r of raw) {
    const key = ROLE_INDEX[r] ?? ROLE_INDEX[r.toLowerCase()];
    if (key) seen.add(key);
  }
  return [...seen];
}

export function computeNavForRoles(roleKeys: string[]): NavGroup[] {
  const roles = NAV_DATA.roles;
  const resources = NAV_DATA.resources;
  const sections = (Array.isArray(NAV_DATA.sections) ? NAV_DATA.sections : [])
    .slice()
    .sort((a, b) => Number(a.order ?? 0) - Number(b.order ?? 0));
  // entradas de nav de TODOS los roles pedidos, dedupe por resource con order mínimo
  const entryByResource = new Map<
    string,
    { resource: string; section: string; order: number; parent: string | null }
  >();
  for (const key of roleKeys) {
    for (const e of roles[key]?.nav ?? []) {
      const resource = typeof e.resource === 'string' ? e.resource : '';
      if (!resource) continue;
      const order = Number(e.order ?? 0);
      const prev = entryByResource.get(resource);
      if (!prev || order < prev.order) {
        entryByResource.set(resource, {
          resource,
          section: typeof e.section === 'string' ? e.section : '',
          order,
          parent: typeof e.parent === 'string' ? e.parent : null,
        });
      }
    }
  }
  const merged = [...entryByResource.values()];
  const groups: NavGroup[] = [];
  for (const section of sections) {
    if (section.id === 'account') continue;
    const inSection = merged.filter((e) => e.section === section.id);
    const tops = inSection
      .filter((e) => e.parent == null)
      .sort((a, b) => a.order - b.order);
    if (tops.length === 0) continue;
    const items: NavItem[] = [];
    const pushItem = (rKey: string) => {
      const res = resources[rKey];
      if (!res) return;
      const slug = String(res.path ?? '').replace(/^\//, '');
      if (!slug) return;
      items.push({
        label: typeof res.label === 'string' && res.label ? res.label : rKey,
        slug,
        icon: null,
      });
    };
    for (const top of tops) {
      pushItem(top.resource);
      const children = inSection
        .filter((e) => e.parent === top.resource)
        .sort((a, b) => a.order - b.order);
      for (const child of children) pushItem(child.resource);
    }
    // ARCH-879-A: los slugs ocultados por el usuario (tombstones) se restan del nav
    // renderizado; ocultar NO es negar (canAccess no los mira).
    const visible = items.filter((i) => !NAV_HIDDEN[i.slug]);
    if (visible.length) {
      groups.push({
        label: typeof section.label === 'string' ? section.label : '',
        items: visible,
      });
    }
  }
  return groups;
}

export function canAccess(slug: string, rawRoles: readonly string[]): boolean {
  const resource = RESOURCE_BY_SLUG[slug];
  if (!resource) return true; // slug no modelado: nunca bloquear por mapeo no resuelto
  const keys = normalizeUserRoles(rawRoles);
  if (keys.length === 0) return false; // autenticado sin rol matcheado: fail-closed
  for (const k of keys) {
    const role = NAV_DATA.roles[k];
    if (!role) continue;
    // Ley de LISTA POSITIVA (kit-runtime 0.23 deniedSlugsForRole, CREW MAJOR-3): los mapas
    // access son MIXTOS — módulos con 'none' explícito, grants de core-services DISPERSOS
    // (clave ausente = negado). Un rol CONCEDE un recurso si su access es view/manage O el
    // recurso aparece en su nav[] (el nav gana incluso sobre un 'none' explícito).
    const level = role.access?.[resource];
    if (level === 'view' || level === 'manage') return true;
    if ((role.nav ?? []).some((e) => e && e.resource === resource)) return true;
  }
  return false;
}


function warnUnmatchedRoles(raw: readonly string[]): void {
  if (raw.length === 0) return;
  console.warn(
    '[role-nav] roles del usuario sin match en el config: ' +
      JSON.stringify(raw) +
      ' — identificadores conocidos (claves de NAV_DATA.roles): ' +
      JSON.stringify(Object.keys(NAV_DATA.roles)) +
      '. Nav vacío (fail-closed).',
  );
}

/** Guarda de ruta por rol — y, desde ARCH-1230, también el backstop de SESIÓN de la superficie
 * privada (el gate de sesión primario sigue siendo el `AuthGuard` de `routes.config.tsx`, que
 * envuelve a éste; esto es defensa en profundidad, no su reemplazo).
 *
 * TRES estados, TRES desenlaces — antes los dos primeros estaban FUNDIDOS en uno solo y el
 * resultado era fail-OPEN:
 *  1. ESPERANDO (`pending` / sin provider): se deja pasar. Denegar mientras carga haría parpadear
 *     una denegación —o peor, un redirect a login— en cada carga de cada pantalla privada.
 *  2. ANÓNIMO RESUELTO (no hay sesión, y ya se sabe): **redirige al login**. Devolver los children
 *     aquí era la mitad B del defecto: la superficie privada se renderizaba entera para un anónimo.
 *     Un "no hay sesión" resuelto no es un estado de espera y no puede tratarse como tal.
 *  3. AUTENTICADO: se adjudica por ROL, exactamente como siempre (`canAccess`, ley L12).
 *
 * Deny sin loops (I1): NUNCA redirige a '/' — '/' redirige a la defaultRoute (privada), así que
 * un deny→'/' con esa privada también denegada vuelve a denegar→'/' de nuevo (loop infinito).
 * En vez de eso: si hay un primer slug del nav del usuario Y ese slug SÍ es accesible, redirige
 * ahí; en cualquier otro caso (nav vacío, o el propio home también denegado — nav item con
 * access 'none') cae a un elemento Kit-skinned de "sin acceso" (`Section`/`EmptyState`,
 * ARCH-960), SIEMPRE keyed (Tarea 4a — un solo camino), nunca una ruta/redirect nueva. */
export function RoleGuard(props: {
  slug: string;
  children: React.ReactNode;
}): React.ReactElement {
  const { t: __i18nT } = useTranslation();
  const { identity, pending } = useIdentity();
  const nav = useRoleNav();
  /** El descriptor Kit-skinned de "sin acceso": el desenlace TERMINAL del guard (ni ruta ni
   * redirect nuevos). Local y no módulo-level porque con la pista i18n su copy sale del `t` que
   * sólo existe dentro del componente. */
  const deny = (): React.ReactElement =>
    React.createElement(
      Section,
      null,
      React.createElement(EmptyState, {
        title: __i18nT("_app.deny-state.title"),
        desc: __i18nT("_app.deny-state.desc"),
      }),
    );
  if (pending) {
    return React.createElement(React.Fragment, null, props.children);
  }
  if (identity === null) {
    return React.createElement(Navigate, { to: "/login", replace: true });
  }
  const roles = identity.roles;
  if (canAccess(props.slug, roles)) {
    return React.createElement(React.Fragment, null, props.children);
  }
  const home = nav[0]?.items[0]?.slug;
  if (home && canAccess(home, roles)) {
    return React.createElement(Navigate, { to: '/' + home, replace: true });
  }
  return deny();
}

/** Nav del usuario real, en el shape PLANO. Sin provider/sin sesión ⇒ `[]` (ARCH-1230: `DEFAULT_NAV`
 * es la proyección del rol default —un OPERADOR— y pintársela a un anónimo filtraba la IA del
 * back-office; ver `useRoleNav` del camino enriquecido para el argumento completo);
 * cargando ⇒ [] (nunca flash privilegiado); cero-match ⇒ [] + warn LOUD (fail-closed). */
export function useRoleNav(): NavGroup[] {
  const { identity, pending } = useIdentity();
  if (pending || identity === null) return [];
  const raw = identity.roles;
  const keys = normalizeUserRoles(raw);
  if (keys.length === 0) {
    warnUnmatchedRoles(raw);
    return [];
  }
  return computeNavForRoles(keys);
}
